(()=>{
const ink='#303a35',muted='#89948c',purple='#7255a4',green='#2f8f6b',red='#b96048';
const text=(x,y,s,col=ink,size=15)=>`<text x="${x}" y="${y}" fill="${col}" font-size="${size}" font-family="system-ui,sans-serif">${s}</text>`;
const line=(x1,y1,x2,y2,col=ink,dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="2.3" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
const dot=(x,y,label,dx=10,dy=-12,col=purple)=>`<circle cx="${x}" cy="${y}" r="4.5" fill="${col}"/>${text(x+dx,y+dy,label,col)}`;
function wrap(body,title){return `<svg class="exam-svg" viewBox="0 0 560 480" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${title}"><title>${title}</title><defs><marker id="exam-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="${muted}"/></marker></defs>${body}</svg>`}
function axes(label='Aggregate expenditure / output',zero=400){return `<path d="M80 45V430M80 ${zero}H480" fill="none" stroke="${muted}" stroke-width="1.6" marker-end="url(#exam-arrow)"/>${text(63,zero+22,'O')}${text(85,25,label)}${text(260,465,'Income / output (Y)')}`}
function ref(){return line(80,400,430,50,muted)+text(443,52,'Y = AS',muted)+`<path d="M113 400 A33 33 0 0 0 103.3 376.7" stroke="${muted}" fill="none"/>`+text(117,385,'45°',muted,13)}
function consumption(){let x=80+60/.35,y=400-60/.35;return wrap(axes('Consumption (C)')+line(80,400,430,50,muted)+text(443,53,'C = Y',muted)+line(80,340,430,112.5,purple)+text(342,100,'C = C̄ + bY',purple)+dot(x,y,'B')+line(x,y,x,400,muted,'5 5')+text(x-7,427,'Yᵦ')+text(39,345,'C̄',purple)+text(110,360,'C > Y',red)+text(355,360,'C < Y',green)+`<path d="M113 400 A33 33 0 0 0 103.3 376.7" stroke="${muted}" fill="none"/>`+text(117,385,'45°',muted,13),'Exam diagram: consumption function, autonomous consumption C-bar, a 45-degree C equals Y line and break-even B.')}
function saving(){let x=80+60/.35;return wrap(axes('Saving (S)',300)+line(80,360,430,237.5,green)+text(313,210,'S = −C̄ + (1 − b)Y',green)+dot(x,300,'B',10,-15)+text(x-7,327,'Yᵦ')+text(32,365,'−C̄',red)+text(110,332,'S < 0',red)+text(355,282,'S > 0',green),'Exam diagram: saving starts at negative autonomous consumption, rises with income and crosses zero at break-even B. The negative intercept is fully visible.')}
function ad(){return wrap(axes()+ref()+line(80,310,430,100,purple)+text(340,87,'AD = C + I',purple)+dot(305,175,'E')+line(305,175,305,400,muted,'5 5')+line(80,175,305,175,muted,'5 5')+text(295,427,'Y*')+text(31,180,'AD*',purple),'Exam diagram: AD intersects the 45-degree AS line at E; drop a perpendicular to equilibrium income Y-star.')}
function si(){return wrap(axes('Planned saving and investment',320)+line(80,380,430,240,green)+text(443,244,'S',green)+line(80,290,430,290,purple)+text(443,295,'I',purple)+dot(305,290,'E',10,-16)+line(305,290,305,320,muted,'5 5')+text(295,347,'Y*')+text(31,385,'−C̄',red),'Exam diagram: upward planned saving intersects horizontal autonomous investment at E; planned S equals planned I.')}
function gap(excess=false){let xf=350,yf=130,ap=excess?78:182,intercept=excess?160:56;let s=axes()+ref();s+=line(80,292,430,82,muted,'6 5')+text(340,62,'ADᶠ',muted);s+=line(80,400-intercept,430,400-intercept-210,purple)+text(443,400-intercept-210+6,'ADᵖ',purple);s+=line(xf,Math.min(yf,ap),xf,400,muted,'5 5');s+=dot(xf,yf,'F',-26,-14,ink)+dot(xf,ap,'E',-26,excess?-10:21,purple);s+=line(xf+15,yf,xf+15,ap,red)+line(xf+9,yf,xf+21,yf,red)+line(xf+9,ap,xf+21,ap,red)+text(xf+30,(yf+ap)/2+5,'EF',red)+text(xf-5,427,'Yf');if(!excess){let q=56/.4;s+=dot(80+q,400-q,'Q',-20,-12)+line(80+q,400-q,80+q,400,muted,'5 5')+text(80+q-6,427,'Y*')}return wrap(s,'Exam diagram: '+(excess?'inflationary':'deflationary')+' gap EF is measured vertically at full-employment output Yf; AD-f is required demand and AD-p is planned demand.')}
function shift(){return wrap(axes()+ref()+line(80,330,430,120,muted)+text(443,124,'AD₀',muted)+line(80,290,430,80,purple)+text(443,84,'AD₁',purple)+dot(255,225,'E₀',-25,-13,muted)+dot(355,125,'E₁',10,-13)+line(255,225,255,400,muted,'5 5')+line(355,125,355,400,muted,'5 5')+text(244,427,'Y₀')+text(344,427,'Y₁')+`<path d="M276 415H335" stroke="${purple}" marker-end="url(#exam-arrow)" fill="none"/>`,'Exam diagram: an autonomous expenditure increase shifts AD up in parallel and raises equilibrium income from Y0 to Y1.')}
function forex(which='none',negative=false){let s=axes('Exchange rate (₹ per US dollar)');s=s.replace('Income / output (Y)','Quantity of US dollars');const x=q=>80+q*2.1,y=e=>400-e*3;let shift=negative?-30:30,D=200+(which==='demand'?shift:0),S=20+(which==='supply'?shift:0),e=(D-S)/3,q=S+e;const d=(D,col,label)=>line(x(20),y((D-20)/2),x(160),y((D-160)/2),col)+text(x(163),y((D-160)/2)+5,label,col);const sup=(S,col,label)=>line(x(S+5),y(5),x(S+100),y(100),col)+text(x(S+100)+5,y(100),label,col);s+=d(200,which==='none'?purple:muted,'D₀')+sup(20,which==='none'?green:muted,'S₀');s+=dot(x(80),y(60),which==='none'?'E':'E₀',-25,-15,muted)+line(80,y(60),x(80),y(60),muted,'5 5')+line(x(80),y(60),x(80),400,muted,'5 5')+text(48,y(60)+6,'R₀')+text(x(80)-8,427,'Q₀');if(which!=='none'){s+=which==='demand'?d(D,purple,'D₁'):sup(S,green,'S₁');s+=dot(x(q),y(e),'E₁',10,-15)+line(80,y(e),x(q),y(e),purple,'5 5')+line(x(q),y(e),x(q),400,purple,'5 5')+text(48,y(e)+6,'R₁',purple)+text(x(q)-8,451,'Q₁',purple)}return wrap(s,'Exam diagram: foreign exchange '+(which==='none'?'equilibrium':(negative?'decrease':'increase')+' in dollar '+which)+'. Rate is quoted in rupees per dollar.')}
const items=[
{id:'consumption',title:'Consumption function & break-even',chapter:'7',source:'IMG_0564',draw:consumption,steps:['Label the horizontal axis Income (Y) and vertical axis Consumption (C).','Draw the C = Y reference line from O at 45°, using equal axis scales.','Start C = C̄ + bY above O on the vertical axis at C̄; keep its slope below one.','Mark intersection B and drop a perpendicular to Yᵦ.'],explain:'At B, C = Y, S = 0, APC = 1 and APS = 0. Below Yᵦ, C > Y and saving is negative; above Yᵦ, saving is positive. The slope of C is MPC.',trap:'Do not start the consumption curve at O when autonomous consumption is positive. Do not confuse break-even with equilibrium income.'},
{id:'saving',title:'Saving function & negative intercept',chapter:'7',source:'IMG_0567',draw:saving,steps:['Label Income (Y) horizontally and Saving (S) vertically; extend the vertical axis below zero.','Start S = −C̄ + (1 − b)Y below O at −C̄.','Draw the upward-sloping saving line; its slope is MPS.','Mark B where saving crosses zero and mark its income Yᵦ.'],explain:'Saving is negative below break-even and positive above it. The negative intercept equals autonomous consumption in magnitude. MPC + MPS = 1.',trap:'The negative intercept must be on the vertical axis, not below the bottom of the drawing or somewhere along the line.'},
{id:'derive',title:'Derive saving from consumption',chapter:'7',source:'IMG_0572',draw:()=>consumption()+saving(),steps:['Draw the consumption curve with the 45° reference line in the upper panel.','Draw saving in a lower panel with the same horizontal income scale.','At Y = 0, C = C̄; mark S = −C̄ below zero.','At B in the upper panel, C = Y; at that same income mark S = 0 below.','For higher Y, the vertical gap Y − C becomes positive saving. Join the saving points.'],explain:'S = Y − C = −C̄ + (1 − b)Y. The two panels have the same break-even income Yᵦ, and the slopes add to one.',trap:'Align the income axes. A positive consumption intercept produces a negative saving intercept, not a positive one.'},
{id:'ad',title:'Equilibrium: AD = AS',chapter:'8',source:'IMG_0575',draw:ad,steps:['Label aggregate expenditure/output vertically and income/output horizontally.','Draw AS = Y as the 45° line from O.','Draw AD = C + I with a positive intercept and slope MPC below one.','Mark E where AD meets AS; drop a perpendicular to equilibrium income Y*.'],explain:'At E, planned expenditure equals planned production. Below Y*, AD > AS: inventories fall and firms expand output. Above Y*, AD < AS: inventories accumulate and firms cut output.',trap:'Do not label the C curve as AD unless investment is zero. Equilibrium need not be full employment.'},
{id:'si',title:'Equilibrium: planned S = planned I',chapter:'8',source:'IMG_0576',draw:si,steps:['Label planned saving/investment vertically and income horizontally.','Draw S upward from a negative intercept.','Draw autonomous I as a horizontal line above zero.','Mark their intersection E and the corresponding income Y*.'],explain:'Y = C + S and AD = C + I. At Y = AD, C + S = C + I, hence S = I. If planned S > I, unsold stocks rise and output falls; if planned S < I, stocks fall and output rises.',trap:'This is equality of ex-ante plans. The ex-post accounting identity alone does not establish equilibrium.'},
{id:'shift',title:'Higher investment & equilibrium income',chapter:'8',source:'IMG_0578',draw:shift,steps:['Draw the 45° AS line and initial AD₀; mark E₀ and Y₀.','An increase in autonomous investment shifts AD upward in parallel to AD₁.','Mark E₁ at its intersection with AS and drop a perpendicular to Y₁.','Show the increase in income Y₁ − Y₀ along the horizontal axis.'],explain:'The vertical AD shift equals ΔI; the horizontal equilibrium-income increase equals kΔI. k = 1/(1 − MPC). The slope stays unchanged if MPC is unchanged.',trap:'Do not rotate AD for an autonomous investment change. Do not equate the vertical expenditure increase with the larger horizontal income increase.'},
{id:'deflation',title:'Deflationary gap & underemployment',chapter:'9',source:'IMG_0584',draw:()=>gap(false),steps:['Draw AS = Y and mark full-employment income Yf.','Draw required ADᶠ through F on AS at Yf.','Draw actual planned ADᵖ below ADᶠ; it meets AS earlier at Q.','At Yf, mark E on ADᵖ. The vertical distance FE is the deflationary gap.','Drop Q to Y*: Y* < Yf identifies underemployment equilibrium.'],explain:'Deflationary Gap = ADᶠ − ADᵖ at Yf. Insufficient demand reduces output and employment and causes unwanted inventories. Expansionary policy raises AD.',trap:'Measure FE vertically at Yf. The horizontal income shortfall Yf − Y* is different from the expenditure gap.'},
{id:'inflation',title:'Inflationary gap at full employment',chapter:'9',source:'IMG_0585',draw:()=>gap(true),steps:['Draw AS = Y and mark Yf on the income axis.','Draw required full-employment ADᶠ through F on AS at Yf.','Draw planned ADᵖ above ADᶠ.','At Yf, mark E on ADᵖ above F; the vertical distance EF is the inflationary gap.'],explain:'Inflationary Gap = ADᵖ − ADᶠ at Yf. Full-employment capacity limits real output; excess demand puts upward pressure on prices. Contractionary policy reduces AD.',trap:'Do not present a notional intersection beyond Yf as feasible extra real output in the full-employment model.'},
{id:'forex',title:'Flexible exchange-rate determination',chapter:'11',source:'IMG_0611',draw:()=>forex(),steps:['Label the vertical axis exchange rate in ₹ per US dollar.','Label the horizontal axis demand/supply or quantity of US dollars.','Draw downward-sloping dollar demand D₀ and upward-sloping supply S₀.','Mark E at the intersection and project to exchange rate R₀ and quantity Q₀.'],explain:'At E, dollar demand equals dollar supply. Above the equilibrium rate, excess dollar supply puts downward pressure on ₹/$; below it, excess demand pushes ₹/$ upward.',trap:'Always identify the quote. A higher ₹/$ rate means a weaker rupee, not a stronger one.'},
{id:'fx-demand-up',title:'Dollar demand rises: rupee depreciates',chapter:'11',source:'IMG_0611',draw:()=>forex('demand'),steps:['Start with D₀, S₀, E₀ and exchange rate R₀.','Shift dollar demand right to D₁ while holding S₀ unchanged.','Mark E₁, the new intersection, and project to R₁.','Show R₁ > R₀: more rupees are required per dollar.'],explain:'Imports, overseas investment or outward payments can raise demand for foreign exchange. The dollar becomes more expensive and the rupee depreciates.',trap:'A demand increase shifts the whole demand curve. It is not merely an upward movement along D₀.'},
{id:'fx-demand-down',title:'Dollar demand falls: rupee appreciates',chapter:'11',source:'IMG_0611',draw:()=>forex('demand',true),steps:['Draw the original equilibrium.','Shift dollar demand left from D₀ to D₁; keep supply unchanged.','Mark the lower new exchange rate R₁.'],explain:'Lower dollar demand reduces ₹/$: fewer rupees buy one dollar, so the rupee appreciates.',trap:'Keep the same ₹/$ quotation in both the graph and explanation.'},
{id:'fx-supply-up',title:'Dollar supply rises: rupee appreciates',chapter:'11',source:'IMG_0612',draw:()=>forex('supply'),steps:['Start with D₀ and S₀ and mark the original equilibrium.','Shift dollar supply right to S₁; hold dollar demand unchanged.','Mark E₁ and its lower rate R₁.'],explain:'More exports or inward foreign investment can raise dollar supply. The ₹/$ rate falls and the rupee appreciates.',trap:'The upward-sloping supply curve moves right/down; do not shift demand instead.'},
{id:'fx-supply-down',title:'Dollar supply falls: rupee depreciates',chapter:'11',source:'IMG_0612',draw:()=>forex('supply',true),steps:['Draw the original equilibrium.','Shift dollar supply left to S₁ while demand stays unchanged.','Mark the higher new rate R₁.'],explain:'Reduced export receipts or inward investment can reduce dollar supply. More rupees are needed per dollar: the rupee depreciates.',trap:'A fall in dollar supply raises its rupee price. Say explicitly which currency depreciates.'},
{id:'circular',title:'Two-sector circular flow',chapter:'2',source:'IMG_0512',draw:()=>window.DIAGRAMS.circular(),steps:['Draw households and firms as separate boxes.','Show factor services from households to firms and factor incomes returning.','Show goods/services from firms to households and consumption expenditure returning.','Label the real flows and money flows distinctly.'],explain:'Production generates income; income finances expenditure; expenditure sustains production. In the simple model, output, income and expenditure have equal value.',trap:'Factor services and goods are real flows. Wages and consumption expenditure are money flows; paired arrows point in opposite directions.'}
];window.EXAM_DIAGRAMS=items;
})();
